"""Writes engine/test/fixtures/rainflow_bandsplit.json: research/analysis/depth/bandsplit.py's rainflow on
three seeded random traces, for engine/test/rainflow.test.ts (#70). CI has no numpy, so the output is committed.

Only bandsplit.py's `turning_points` and `rainflow` functions are run: they are read out of the file with `ast`,
so its scipy import and simulation never execute. Needs numpy.

    python engine/test/fixtures/rainflow_bandsplit.py   (not -I: numpy may live in user site-packages)
"""

import ast
import json
import pathlib

import numpy as np

ROOT = pathlib.Path(__file__).resolve().parents[3]
SRC = ROOT / "research" / "analysis" / "depth" / "bandsplit.py"
OUT = pathlib.Path(__file__).with_suffix(".json")

tree = ast.parse(SRC.read_text(encoding="utf-8"))
funcs = [n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name in ("turning_points", "rainflow")]
assert [f.name for f in funcs] == ["turning_points", "rainflow"], [f.name for f in funcs]
ns = {"np": np}
exec(compile(ast.Module(body=funcs, type_ignores=[]), str(SRC), "exec"), ns)


def traces():
    # No two consecutive values are equal in any of these (see "plateau" below for why that matters).
    yield "uniform_60_seed1", np.random.default_rng(1).random(60)
    yield "walk_300_seed2", np.cumsum(np.random.default_rng(2).standard_normal(300))
    yield "soc_like_500_seed3", 0.5 + 0.45 * np.sin(np.cumsum(np.random.default_rng(3).normal(0, 0.3, 500)))


def run(x):
    return [[float(r), float(c)] for r, c in ns["rainflow"](np.asarray(x, dtype=float))]


out = {
    "note": "Generated by engine/test/fixtures/rainflow_bandsplit.py from research/analysis/depth/bandsplit.py "
    "(turning_points and rainflow only) with numpy "
    + np.__version__
    + ". cycles are [range, count] in bandsplit's output order.",
    "traces": [{"name": n, "x": [float(v) for v in x], "cycles": run(x)} for n, x in traces()],
    # bandsplit keeps both ends of a flat run as turning points; on 0, 1, 1, 0 that drops the swing.
    "plateau": {"x": [0.0, 1.0, 1.0, 0.0], "cycles": run([0.0, 1.0, 1.0, 0.0])},
}
OUT.write_text(json.dumps(out, indent=1) + "\n", encoding="utf-8", newline="\n")
print(f"wrote {OUT.relative_to(ROOT)}: " + ", ".join(f"{t['name']} {len(t['cycles'])} cycles" for t in out["traces"]))
print("plateau case:", out["plateau"]["cycles"])
